from collections import defaultdict, deque

def can_white_win(n, edges, colors):
    graph = defaultdict(list)
    for v, u in edges:
        graph[v].append(u)
        graph[u].append(v)

    # Check if there's a path of three vertices in white starting from any uncolored vertex
    for i in range(1, n + 1):
        if colors[i - 1] == 'N':
            queue = deque([(i, 0)])  # (vertex, depth)
            visited = set([i])
            while queue:
                v, depth = queue.popleft()
                if depth == 2:
                    for neighbor in graph[v]:
                        if colors[neighbor - 1] == 'W':
                            return 'White'
                if depth < 2:
                    for neighbor in graph[v]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            queue.append((neighbor, depth + 1))
    return 'Draw'

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1
    results = []

    for _ in range(T):
        n = int(data[index])
        index += 1
        edges = []
        for _ in range(n - 1):
            v = int(data[index])
            u = int(data[index + 1])
            edges.append((v, u))
            index += 2
        colors = data[index]
        index += 1
        results.append(can_white_win(n, edges, colors))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
